  { key: "Stage", label: "Stage" },
  { key: "Severity", label: "Severity" },
  { key: "Occurrences", label: "Occurrences", num: true },
  { key: "Bills Affected", label: "Bills Affected", num: true },
  { key: "Open", label: "Open", num: true },
  { key: "Resolved %", label: "Resolved %", num: true },
  { key: "Resolvable", label: "Resolvable" },
  { key: "Last Seen", label: "Last Seen" }
];
const NUM_KEYS = ["Code", "Occurrences", "Bills Affected", "Open", "Resolved %", "severity_code"];
