// range when a code fires at more than one level), so sort it by the number.
const SORT_BY = { "Severity": "severity_code" };
const fmt = (v) => (Number(v) || 0).toLocaleString();
function App() {
  const [model, setModel] = useState(appsmith.model || {});
  // Lowest resolution rate first: that is the operational signal, not raw volume.
  const [sortKey, setSortKey] = useState("Resolved %");
  const [sortDir, setSortDir] = useState("asc");
  const [page, setPage] = useState(1);
  const [pageSize, setPageSize] = useState(20);

  useEffect(() => {
    const update = () => setModel({ ...(appsmith.model || {}) });
    update();
    if (typeof appsmith.onModelChange === "function") appsmith.onModelChange(update);
    const id = setInterval(update, 400);
    return () => clearInterval(id);
  }, []);

  const data = (model && model.data) || [];
  const stage = model.stage || "";
  const sev = model.sev || "";
  const cat = model.cat || "";
  const q = model.q || "";

  const filtered = useMemo(() => {
    const needle = q.trim().toLowerCase();
    return data.filter((r) => {
      if (stage && String(r["Stage"]) !== stage) return false;
      if (sev && String(r["Severity"]) !== sev) return false;
      if (cat && String(r["Category"]) !== cat) return false;
      if (!needle) return true;
      return String(r["Code"]).indexOf(needle) !== -1 ||
             String(r["Check"] || "").toLowerCase().indexOf(needle) !== -1;
    });
  }, [data, stage, sev, cat, q]);

  const rows = useMemo(() => {
    const list = filtered.slice();
    const sk = SORT_BY[sortKey] || sortKey;
    list.sort(function (a, b) {
      if (NUM_KEYS.indexOf(sk) !== -1) {
        const av = Number(a[sk]), bv = Number(b[sk]);
        const aa = isNaN(av) ? -1 : av, bb = isNaN(bv) ? -1 : bv;
        if (aa !== bb) return sortDir === "asc" ? aa - bb : bb - aa;
        // Tie-break by volume so the biggest problems lead within a rate band.
        return (Number(b["Occurrences"]) || 0) - (Number(a["Occurrences"]) || 0);
      }
      const av = a[sk] == null ? "" : String(a[sk]);
      const bv = b[sk] == null ? "" : String(b[sk]);
      return sortDir === "asc" ? av.localeCompare(bv) : bv.localeCompare(av);
    });
    return list;
  }, [filtered, sortKey, sortDir]);

  useEffect(() => { setPage(1); }, [rows.length]);

  const totalPages = Math.max(1, Math.ceil(rows.length / pageSize));
  const safePage = Math.min(page, totalPages);
  const pageRows = rows.slice((safePage - 1) * pageSize, (safePage - 1) * pageSize + pageSize);

  const onSort = (k) => {
    if (k === sortKey) setSortDir(sortDir === "asc" ? "desc" : "asc");
    else { setSortKey(k); setSortDir(NUM_KEYS.indexOf(SORT_BY[k] || k) !== -1 ? "desc" : "asc"); }
  };
  const goToPage = (p) => setPage(Math.max(1, Math.min(totalPages, p)));
  const openBills = (row) => {
    appsmith.updateModel({ selectedRow: row });
    if (typeof appsmith.triggerEvent === "function") appsmith.triggerEvent("onRowAction");
  };

  if (model.isLoading) return React.createElement("div", { className: "skel" }, "Loading validation codes...");

  const arrows = (k) => React.createElement("span", { className: "sort" },
    React.createElement("span", { className: (sortKey === k && sortDir === "asc") ? "active" : "" }, "▲"),
    React.createElement("span", { className: (sortKey === k && sortDir === "desc") ? "active" : "" }, "▼"));

  const cell = (r, c) => {
