      const v = r["Resolved %"];
      if (v == null) return React.createElement("span", { className: "no" }, "—");
      const cls = v < 25 ? "p-bad" : v < 75 ? "p-mid" : "p-good";
      return React.createElement("span", { className: "pct " + cls }, v + "%");
    }
    if (c.key === "Resolvable") {
      return r["Resolvable"]
        ? React.createElement("span", { className: "badge b-info" }, "Yes")
        : React.createElement("span", { className: "badge b-error" }, "No");
    }
    if (c.num) {
      // Bills Affected is not computed when no customer is picked, so show it as
      // not-applicable rather than as a zero that would read like real data.
      if (r[c.key] == null) return React.createElement("span", { className: "no" }, "—");
      return React.createElement("span", null, fmt(r[c.key]));
    }
    const v = r[c.key];
    return v == null ? "" : String(v);
  };

  return React.createElement("div", { className: "wrap" },
    React.createElement("div", { className: "meta" },
      rows.length === data.length
        ? rows.length + " codes"
        : rows.length + " of " + data.length + " codes"),
    React.createElement("div", { className: "scroll" },
      React.createElement("table", { className: "tbl" },
        React.createElement("thead", null,
          React.createElement("tr", null,
            COLS.map((c) => React.createElement("th", { key: c.key, onClick: () => onSort(c.key) }, c.label, arrows(c.key))),
            React.createElement("th", { className: "noSort", key: "__a" }, ""))),
        React.createElement("tbody", null,
          pageRows.length === 0
            ? React.createElement("tr", null, React.createElement("td", { className: "empty", colSpan: COLS.length + 1 }, "No codes match these filters"))
            : pageRows.map((r, i) => React.createElement("tr", { key: String(r["Code"]) + "_" + String(r["Category"]) + "_" + i },
                COLS.map((c) => React.createElement("td", { key: c.key, className: c.num ? "num" : null },
                  c.wrap ? React.createElement("div", { style: { maxWidth: c.wrap + "px" } }, cell(r, c)) : cell(r, c))),
                React.createElement("td", { key: "__a" },
                  React.createElement("a", { className: "maplink", onClick: () => openBills(r) }, "View bills"))))))),
    React.createElement("div", { className: "pager" },
      React.createElement("button", { className: "pbtn", disabled: safePage <= 1, onClick: () => goToPage(safePage - 1) }, "‹"),
      React.createElement("span", { className: "pnum" }, safePage),
      React.createElement("span", { className: "gotolbl" }, "of " + totalPages),
      React.createElement("button", { className: "pbtn", disabled: safePage >= totalPages, onClick: () => goToPage(safePage + 1) }, "›"),
      React.createElement("select", { className: "psize", value: pageSize,
        onChange: (e) => { setPageSize(Number(e.target.value)); setPage(1); } },
        [10, 20, 30, 50, 100].map((n2) => React.createElement("option", { key: n2, value: n2 }, n2 + "/page")))));
}

ReactDOM.render(React.createElement(App, null), document.getElementById("root"));

